def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for r0 in range(h):
        common=grid[r0][:]
        for r1 in range(r0,h):
            if r1>r0:
                common=[common[c] if common[c]==grid[r1][c] else -1 for c in range(w)]
            if r1-r0+1<5: continue
            c=0
            while c<w:
                if common[c]<0:
                    c+=1; continue
                color=common[c]; c1=c+1
                while c1<w and common[c1]==color: c1+=1
                if c1-c>=5:
                    for rr in range(r0,r1+1):
                        for cc in range(c,c1): out[rr][cc]=4
                c=c1
    return out
